// Extension d'essai du lot 2 (protocole 1.0) : lecture du modèle, opération explicite, sélection.
planche.sur("commande.poser-boite", async () => {
  await planche.operation.ouvrir("Poser une boîte");
  const elements = await planche.modele.boite([0, 0, 0], 1, 1, 1);
  const objet = await planche.modele.grouper(elements, "Boîte d'essai");
  await planche.selection.definir([objet]);
  const fin = await planche.operation.valider();
  return { objet, crees: fin.crees.length };
});
planche.sur("commande.compter", async () => {
  const m = await planche.modele.lire();
  const selection = await planche.selection.lire();
  return { faces: m.faces.length, aretes: m.aretes.length, objets: m.objets.length, selection: selection.length };
});
