});
planche.sur("commande.deux-operations", async () => {
  await planche.operation.ouvrir("Première");
  try {
    await planche.operation.ouvrir("Seconde");
  } catch (e) {
    await planche.operation.abandonner();
    return e.name;
  }
  return "aucune erreur";
});
